begin perform public.fc_command('publish',jsonb_build_object('id',s1,'operation',gen_random_uuid(),'changes',jsonb_build_array(jsonb_build_object('id',f1,'estado','disponible')))); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: administrador no publica'; end if; end;
