begin perform public.fc_command('station_save',jsonb_build_object('id',gen_random_uuid(),'empresa_id',e1,'ciudad_id',city,'nombre','Sin direccion','direccion','','combustibles',jsonb_build_array(f1))); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: estacion requiere direccion'; end if; end;
perform public.fc_command('company_state',jsonb_build_object('id',e1,'activo',false));
