perform public.fc_command('station_state',jsonb_build_object('id',sx,'activo',false));
perform public.fc_command('company_state',jsonb_build_object('id',e1,'activo',true));
if not coalesce((not(select activo from public.estaciones where id=sx)),false) then raise exception 'Fallo: reactivar empresa no reactiva estacion'; end if;
update public.perfiles set rol='responsable',activo=true where id=m1;
update public.perfiles set rol='conductor',activo=true where id=m2;
