begin perform public.fc_command('assignment_add',jsonb_build_object('id',gen_random_uuid(),'vinculacion_id',v1,'estacion_id',s2)); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: no asigna estaciones de otra empresa'; end if; end;
begin perform public.fc_command('assignment_add',jsonb_build_object('id',gen_random_uuid(),'vinculacion_id',v1,'estacion_id',s1)); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: no duplica asignacion vigente'; end if; end;
perform set_config('request.jwt.claim.sub',m1::text,true);
if not coalesce((jsonb_array_length(public.fc_query('catalog','{"mode":"assigned"}')->'rows')=1),false) then raise exception 'Fallo: mis estaciones solo incluye asignadas'; end if;
begin perform public.fc_command('publish',jsonb_build_object('id',s2,'operation',gen_random_uuid(),'changes',jsonb_build_array(jsonb_build_object('id',f1,'estado','disponible')))); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: no publica en otra estacion'; end if; end;
begin perform public.fc_command('publish',jsonb_build_object('id',s1,'operation',gen_random_uuid(),'changes','[]'::jsonb)); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: no publica lote vacio'; end if; end;
begin perform public.fc_command('publish',jsonb_build_object('id',s1,'operation',gen_random_uuid(),'changes',jsonb_build_array(jsonb_build_object('id',f1,'estado','sin_actualizar')))); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: estado calculado no se publica'; end if; end;
begin perform public.fc_command('publish',jsonb_build_object('id',s1,'operation',gen_random_uuid(),'changes',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'estado','disponible')))); raise exception 'OPERACION_ACEPTADA'; exception when others then if sqlerrm='OPERACION_ACEPTADA' then raise exception 'Fallo: combustible ajeno rechazado'; end if; end;
null;
perform public.fc_command('publish',jsonb_build_object('id',s1,'operation',op,'changes',jsonb_build_array(jsonb_build_object('id',f1,'estado','limitada'))));
perform public.fc_command('publish',jsonb_build_object('id',s1,'operation',op,'changes',jsonb_build_array(jsonb_build_object('id',f1,'estado','limitada'))));
if not coalesce(((select count(*)=1 from public.historial_disponibilidad where operacion_id=op)),false) then raise exception 'Fallo: publicacion idempotente'; end if;
if not coalesce(((select autor_perfil_id=m1 from public.historial_disponibilidad where operacion_id=op)),false) then raise exception 'Fallo: autor del servidor'; end if;
if not coalesce((private.fc_station(s1)->'combustibles' @> jsonb_build_array(jsonb_build_object('id',f1,'estado','limitada'))),false) then raise exception 'Fallo: consulta refleja publicacion'; end if;
