if not coalesce((private.fc_station(s1)->'combustibles' @> jsonb_build_array(jsonb_build_object('id',f1,'estado','sin_actualizar'))),false) then raise exception 'Fallo: vence al alcanzar dos horas'; end if;
update public.historial_disponibilidad set registrado_en=now()-interval '1 hour' where operacion_id=op;
