perform public.fc_command('favorite',jsonb_build_object('id',s1,'activo',false));
if not coalesce(((select not activo from public.favoritas where perfil_id=m2 and estacion_id=s1)),false) then raise exception 'Fallo: quitar favorita aplica baja logica'; end if;
perform public.fc_command('favorite',jsonb_build_object('id',s1,'activo',true));
