perform set_config('request.jwt.claim.sub',ad::text,true);
if not coalesce((jsonb_array_length(public.fc_query('catalog',jsonb_build_object('mode','favorites','perfil_id',m2))->'rows')=0),false) then raise exception 'Fallo: admin no lee favoritas de otra cuenta'; end if;
perform public.fc_command('station_state',jsonb_build_object('id',s1,'activo',false));
perform set_config('request.jwt.claim.sub',m2::text,true);
if not coalesce(((public.fc_query('catalog','{"mode":"favorites"}')->'rows'->0->>'disponible')='false'),false) then raise exception 'Fallo: favorita inactiva conserva referencia minima'; end if;
